'use strict';

// changelogData.js — GENERATED by tools/build-changelog.js. Never edit by hand; the next
// release overwrites it. Newest first.

const CHANGELOG_REPO = 'https://github.com/Hinnful/Evermist';

const CHANGELOG = [
  {"version":"2.11.0","date":"2026-09-12","note":"Rooms can have holes","body":"A Cut or a Trim landing wholly inside a room now leaves a hole in that room instead of being refused.\nThe hole belongs to the room: it moves with it, saves and reloads with it, and one undo takes an edit back.\nThe inner outline carries the same vertex handles as the outer one, including corner radius and doors.\nA shape drawn inside a hole is a separate room and stays put when the room around it moves.\nCutting a room in half through its hole gives each half its own part of it."},
  {"version":"2.10.7","date":"2026-09-12","note":"Merge and Cut out switch off after one shape","body":"Merge and Cut out used to stay on until you pressed them again, so a room drawn later got repaired instead of made. They now apply to one shape and switch off, including when the repair is refused or lands on nothing.","tag":"v2.10.7"},
  {"version":"2.10.6","date":"2026-09-12","note":"Read what each version changed, without leaving the app","body":"What's new lists every release, newest first, and marks the one you are running.\nOpen a release to read the full note it shipped with, or to jump to its page on GitHub.\nA downloaded update now says so in the top corner, and the restart button is on that card.\nThe first start after an update tells you which version arrived.\nWhat's new sits in the About footer, under the help button.","tag":"v2.10.6"},
  {"version":"2.10.5","date":"2026-09-11","note":"Doors hold their place, and a scene can leave its group","body":"Adding a corner to a wall no longer throws its door across the room.\nYou can drag a scene back out of a group. The Ungrouped heading stays in the library even when it is empty.","tag":"v2.10.5"},
  {"version":"2.10.4","date":"2026-09-11","note":"A new screen opens without rebuilding its fog","body":"Opening a screen while the advanced fog sliders are away from their defaults no longer costs a few seconds of building a fog texture twice.","tag":"v2.10.4"},
  {"version":"2.10.3","date":"2026-09-11","note":"Two maps keep the view you set up","body":"Pressing Two maps keeps the zoom and the part of the floor you were looking at.\nDragging the divider keeps it too, and so does the second map arriving.","tag":"v2.10.3"},
  {"version":"2.10.2","date":"2026-09-11","note":"Adding a second map no longer stalls the screens","body":"Opening a second map no longer drops every window to a crawl for several seconds.\nThe Player screen now carries fog and map alone - no app name, no loading line.\nThe fog no longer shows a faint diagonal band on a narrow Player screen.\nSwitching to two maps no longer flashes black before the fog arrives.","tag":"v2.10.2"},
  {"version":"2.10.1","date":"2026-09-11","note":"Smoother fog for the players, and no pause when maps change","body":"The players' fog is drawn by the graphics card, so it stays smooth on big maps and in two-map mode.\nOpening a scene no longer rebuilds the fog texture, which used to hold the player screen for a second or two.\nThe two-map player screen is prepared ahead of the button, so it opens quicker.\nRooms and their labels appear as soon as a scene opens, instead of waiting for a mouse move.\nThe diagnostic overlay shows a frame rate, and a slow spell reaches the log on its own.","tag":"v2.10.1"},
  {"version":"2.10.0","date":"2026-09-10","note":"Show two floors at once, on both screens","body":"The DM window's map area splits in two, and each half is a whole map with its own scene, camera, grid, rooms and fog.\nThe Player screen splits the same way, with a chasm painted between the two floors.\nA click on either map selects it and acts on it in the same press.\nThe second map opens empty and waits for you to pick it from the library.\nClosing one map goes back to a single map, and the TV keeps showing it.\nThe Player window keeps its fullscreen when you split and when you go back.\nThe music bubble keeps its shape when nothing is playing.","tag":"v2.10.0"},
  {"version":"2.9.0","date":"2026-09-09","note":"Fit the grid to the map by dragging on it","body":"Drag a square across the map's own cells and the grid takes its size and position from them.\nThe count of cells the square covers is a guess. A stepper on the map corrects it.\nThe square stays put after the drag. Move it to slide the grid, or pull its corner to resize.\nHex grids calibrate too. You drag a hexagon, and you press on a cell's centre.\nA magnifier follows the pointer while you aim. An animated map holds still until you are done.\nCalibrate sits beside Reset in the Grid panel and lights up while it has the map.\nThe Offset fields are gone. Grid Reset still puts the grid back to zero.","tag":"v2.9.0"},
  {"version":"2.8.2","date":"2026-09-08","note":"Music from inside the app, and a way back from a bad update","body":"A control at the top of the DM window plays the audio files in the app's music folder, crossfading between tracks. Paste a YouTube video or playlist link to download more.\nVolume, a filter and a per-track delete sit in the panel. Tracks loop, nothing reaches the Player, and music never enters the backup zip.\nThe app can now install an older version when one is offered, so a release that goes wrong can be taken back rather than waited out.\nA downloaded update applies only when Restart is pressed. Closing the app never installs one.\nSetting a corner radius twice no longer leaves the second one on the room after Ctrl+Z.\nA map pushed to the Player no longer tears down a clip that is still loading.\nA backup names any scene whose map file was missing, and still goes out.\nUnder the hood: every push now builds all three installers and drives the packaged Windows app through the full test suite before a release exists.","tag":"v2.8.2"},
  {"version":"2.8.1","date":"2026-09-08","note":"A lighter music panel, and pause instead of stop","body":"The track panel is two rows of chrome instead of five: search and add on top, volume pinned below the list. It shuts on a click anywhere off it.\nPause replaces stop and keeps its position, so a second press picks the track back up where it was.\nThe Add music panel looks a pasted link up on its own, with no Look up button, and carries the scene library's selection bar and Select all.\nA running download shows its progress on the pill, and reopening the panel mid-download keeps the queue.\nDownloads pick the highest-quality audio stream rather than preferring a container, which was costing bitrate.\nUpdate downloader appears only when a newer yt-dlp release exists.\nThe music UI now uses the app's own field, slider, button and checkbox styles throughout.\nThe Add music panel moved to src/musicDownload.js."},
  {"version":"2.8.0","date":"2026-09-08","note":"Music plays from inside the app, no browser tab","body":"A control at the top of the DM window plays the audio files in the app's music folder, crossfading between tracks.\nPaste a YouTube video or playlist link to download tracks, with the ones already on disk marked.\nyt-dlp ships pinned and outside the asar. No ffmpeg - audio downloads without conversion.\nVolume, a filter and a per-track delete sit in the panel. Tracks loop, nothing reaches the Player, and music never enters the backup zip.\nA rig run is muted at launch, so no scenario can make a sound."},
  {"version":"2.7.3","date":"2026-09-08","note":"Undo takes back a corner radius, and no run fails at random","body":"Setting a corner radius twice no longer leaves the second one on the room after Ctrl+Z.\nA map push that overtakes a still-loading one no longer tears down the clip it is reading.\nA group rename commits through the field's own listener, so a run no longer fails at random.\nEvery main-process send is guarded, a half-copied map is unlinked, and a damaged restore entry settles.\nA backup names the scenes whose map file was gone, and a restore claims no path the zip never held.\nThe map library failing to open now reports, instead of throwing on every save after it.\nUnreachable code is out, and the remaining modules run under strict mode.\nMutation targets come from function names rather than line ranges that had drifted off them."},
  {"version":"2.7.2","date":"2026-09-08","note":"An update installs only when the button is pressed","body":"A downloaded update no longer applies when the app is closed. It waits for Restart to update.\nDownloading still happens in the background, so the button applies straight away.\nDocs record the rule and the settled call that release publishing stays manual."},
  {"version":"2.7.1","date":"2026-09-07","note":"Point macOS at the releases page when it cannot self-update","body":"macOS now shows a manual-update line in the About block, with a button that opens the releases page.\nWindows and Linux keep the automatic update path unchanged.\nThe releases URL is fixed in main, so the renderer cannot ask for an arbitrary one.\nDocs record the installer, CI and version-gating decisions that shipped with 2.7.0.","tag":"v2.7.1"},
  {"version":"2.7.0","date":"2026-09-07","note":"Install once, and every update after that is one click","body":"Windows now ships an NSIS installer instead of a portable .exe.\nAn installed copy downloads new versions in the background and offers a restart from the About footer.\nmacOS is excluded: an unsigned .dmg cannot pass the updater's signature check, so it stays a manual download.\nrelease.yml now uploads latest.yml and the blockmaps alongside the installers.\nNew structure test refuses a script or stylesheet that index.html loads but build.files does not ship.\nBoth READMEs correct the claim that nothing ever leaves the machine.","tag":"v2.7.0"},
  {"version":"2.6.2","date":"2026-09-07","note":"Gate every build on a green suite and a matching tag","body":"New Tests workflow runs npm test on every branch push and pull request.\nrelease.yml gains a verify job, and the three builds now wait on it.\n.github/check-version.js refuses a release whose tag and package.json version disagree.\nBoth test paths skip the Electron binary download; the build jobs still fetch it.\nThe ledger size notice re-arms after a split instead of banking the gain as silence."},
  {"version":"2.6.1","date":"2026-09-04","note":"Each mode gets its own bar, and the shapes share one button","body":"Rooms and Effects each show only their own tools; a tool a mode cannot use is absent rather than greyed.\nRectangle, Circle, Polygon and Cone stand behind one shape button, with a flyout on right click.\nMerge and Cut out moved onto the bar, the New button is gone, and pressing a lit repair disarms it.\nEntering Effects disarms an armed repair, since that bar carries no button for it.\nThe Rooms/Effects switch is a sunken track at the end of the bar.\nSnap and Straighten show they are on with a fill and an underline instead of the picked tool's outlined box.\nThe strip above the bar carries only the picked tool's options, and goes blank without moving the bar.\nDocs, the dm-ui skill and the acceptance scenarios updated to match."},
  {"version":"2.6.0","date":"2026-09-04","note":"Repair a room in one gesture: Join, Trim and Cut","body":"Join merges every room a drawn shape lands on, taking the most hidden fog mode of the parts.\nTrim removes a drawn shape from the rooms it lands on, cutting a notch or splitting one in two.\nCut splits a room along a click path and leaves its halves flush.\nA repair that would leave a hole in a room is refused whole and spends no undo.\nRounding and door marks are dropped from a repaired room rather than remapped.\npolygon-clipping 0.15.7 vendored to lib/, with the pure kernel in src/roomOps.js.\ndocs/DECISIONS.md split by topic into docs/decisions/."},
  {"version":"2.5.4","date":"2026-09-01","note":"One edge on every floating panel, and ember on hex grids","body":"The room card, the advanced fog panel, the import modal and the confirm dialog read the shared panel surface instead of their own hex; the scene library popup takes the shared border.\nAn effect relights the grid in ember on hex maps, not just square ones.\nThe ember pass walks only the cells each effect covers rather than the whole viewport.\nRig: floating panels report one edge (control-panel H), the relight covers every grid type (effects J)."},
  {"version":"2.5.3","date":"2026-09-01","note":"Draw Rooms places the doors the plan implies","body":"An opening two rooms share becomes a door. One on an outside wall does not - windows and entrances stay hand-marked.\nDerived doors are ordinary doors: same size dials, same click to remove, saved with the scene.\nThe import notice and the replace-rooms dialog now name the door count alongside the rooms."},
  {"version":"2.5.2","date":"2026-08-30","note":"Float the settings tabs, and give the DM chrome one surface","body":"The Fog/Grid/Player tabs moved out of the settings panel into their own bar above it. Picking a tab opens the panel, picking it again shuts it, and the open pane is remembered.\nThe Scenes button, the bottom toolbar, the tab bar and the settings panel now share one surface, defined once in base.css.\nReset Fog Settings and Reset Grid Settings are icon buttons beside the selector they reset, and ask before resetting.\nRemoved the UI scale slider.\nThe About box moved into the shortcut legend, so one corner button opens both.\nAdvanced now stays lit in the animation row whenever the fog is running on hand-dialled settings.\nNew acceptance scenario for the control panel.","tag":"v2.5.2"},
  {"version":"2.5.1","date":"2026-08-30","note":"Show fog while the Player loads, and keep map data in one place","body":"The Player window opens on a drifting fog screen instead of a flat navy sheet, and swaps to the map once it has decoded.\nA Player window is prepared in the background at startup, so the button no longer waits on a page load.\nMap data always lives in the OS per-user folder - the Windows portable build no longer writes beside the .exe.\nThe Player's map-request retry starts only once the DM is holding the window, so a stale request can no longer re-send a map mid-session.\nCover the Player window's whole life in the test rig."},
  {"version":"2.5.0","date":"2026-08-30","note":"Mark the doors, and clear the fog off shared walls","body":"Door tool: click a wall to open one grid cell as an exit, click it again to close.\nA door shows in the most revealed state of every room whose wall runs through it, half-shroud included.\nThe grid draws on the DM screen while the Door tool is picked, and each wall carries ticks at its cell boundaries.\nTwo revealed rooms that share a wall no longer leave a band of fog standing on it.\nSelect is the tool at launch, in both placement modes.\nComment share of shipped JavaScript now ratchets down under its own guard."},
  {"version":"2.4.1","date":"2026-08-29","note":"Cut dead code, and fix the Player's map surround","body":"The area around the map on the Player now follows the fog colour instead of staying navy.\nRemove unreferenced code from fog, tools, sceneManager and state, and a dead style rule.\nRemove the unused set-fullscreen route from the shell; the Player's own toggle is unchanged.\nDrop two Electron 28 workarounds the current engine no longer needs, in the colour picker and the Advanced panel.\nKeep the grid offset width fix and correct its comment: it is required on any engine, not an old-engine workaround.\nSplit the decisions ledger into topic files under docs/decisions, and state how each doc is allowed to grow.\nGuard ARCHITECTURE.md on size and tense, and refuse any command that would open an app window on the screen.\nThe rig parks its windows before the first app starts, so a run no longer takes focus per scenario."},
  {"version":"2.4.0","date":"2026-08-29","note":"Group scenes, and find one by name","body":"The scene list becomes a popup over the map: search, bulk actions in a contextual bar, and cards that show a whole name.\nScenes carry a group, shown as a collapsible heading you drag cards into. Deleting a heading deletes no maps.\nThe group rides the scene through IndexedDB and the backup zip.\nRenaming a group onto a name already in use asks before merging.\nA reorder is refused when the list is filtered, so a drag can no longer renumber scenes it never showed.\nCommitting a scene name no longer rebuilds the list under the click that ended the edit.\nNew acceptance scenario for grouping; ARCHITECTURE and CLAUDE.md carry the new module.","tag":"v2.4.0"},
  {"version":"2.3.2","date":"2026-08-28","note":"Send a scene switch to the Player once, and test what reaches it","body":"A scene switch delivers the map once. The second delivery landed while the Player's cover was still closing, so the swap could show on screen.\nGroup the test rig by feature: drawing, editing and effects each cover one feature end to end and check what reached the Player.\nThe rig no longer takes the screen. Both windows run off-screen and keep painting, so the machine stays usable during a run.\nFix the Player window coming up invisible. Windows reported it occluded and Chromium stopped painting it.\nStop an Electron startup error failing runs, and check the preload directly on both windows instead.\nRead the fire's brightness across frames, so the corner-rounding check is no longer inside its own noise."},
  {"version":"2.3.1","date":"2026-08-28","note":"Fix a batch of bugs across sending, drawing and scenes","body":"Send sends the view as well as the fog, from the button as from Space.\nA stroke or pan that leaves the map keeps going, and its reveal reaches the Player.\nRenaming or reordering a scene no longer reverts the last reveal.\nA second dialog raised over one already on screen waits its turn instead of vanishing.\nReplacing the map on a scene that holds only effects no longer moves them.\nThe Player rebuilds its fog mask on a height change, not only a width change.\nSelecting a room no longer spends an undo step.\nThe ember grid follows an effect's rounded corners, and a restore finishes at 100%."},
  {"version":"2.3.0","date":"2026-08-26","note":"Mark burning ground on the map, and draw cones","body":"Map effects: draw an area of burning ground that reaches the Player and persists to scene, backup and undo.\nRooms/Effects switch decides which the shape tools draw, in its own pill beside the toolbar.\nCone tool in both modes - drag from the point of origin, fixed 53 degree spread, straighten walls rounds the direction to 15.\nThe row above the toolbar is one pill, holding the fog trio or the material picker alongside brush size.\nThe map grid relights in ember inside an effect zone, so covered squares stay countable.\nDocs, skills and rig scenarios updated alongside."},
  {"version":"2.2.0","date":"2026-08-14","note":"Import many maps at once, and take the grid from the floor plan","body":"The file picker takes many maps; they import one at a time, land you on the first, and report failures once at the end.\nA .zip on its own still restores a backup; one inside a multi-file selection imports nothing.\ncreateNewScene now resolves when the map is on screen or refused, settling on every failure exit.\nGrid Size comes from the map's floor plan at import, clamped to the control's range, and Draw Rooms never overwrites it later.\nGrid settings persist per scene, Grid Reset included, and a new import keeps the grid's look but not its cell size or offset.\nvttDerivePlan also reports the plan's size in grid squares and its pixels per square.\nAdds rig scenarios for grid persistence, the derived grid and the batch import."},
  {"version":"2.1.0","date":"2026-08-13","note":"Compress oversized animated maps on import","body":"New Compression switch in the scene list re-encodes animated maps over 3840x2160 to fit it, off by default and explained once per run.\nAuto-drawn rooms scale onto the loaded map instead of the floor plan's own pixel space, and the plan is now resolved before the map is touched.\nThe DM no longer uploads a map texture for an animated map, which it never drew.\nDropped mapDirty, the requestVideoFrameCallback fallback and the USE_DISPLAY_SIZING lever.\nTest rigs consolidated into tools/rig; the transition-capture pair is gone.\nDocs split one question per file with PRODUCT.md added, a guard hook each, and CLAUDE.md trimmed to rules."},
  {"version":"2.0.0","date":"2026-08-10","note":"Rewrite both READMEs","body":"Reorder the feature sections: rooms and notes, module import, homebrew, floor plan last\nRename \"shape\" to \"room\", and use the Revealed / Shrouded / Half-shrouded labels\nReplace the TV setup prose with numbered steps\nMove Manual mode and the minimap into Everything else\nNew assets: draw-rooms.gif, module-text.gif, dm-window.png","tag":"v2.0.0"},
  {"version":"1.7.9","date":"2026-08-09","note":"Fix the fullscreen button, cloud morph and toolbar divider","body":"Cloud morph on animated maps now runs at the same rate as on image maps.\nThe Player fullscreen button shows whether the Player is fullscreen.\nCtrl+Z goes back to the fog once you click away from a room card.\nRemoved the toolbar hairline between the fog modes and the switches.\nThe minimap reuses one scratch canvas instead of allocating per redraw.\nA non-finite display scale factor now falls back to 1.\nDocs, hooks and skill notes updated alongside."},
  {"version":"1.7.8","date":"2026-08-09","note":"Preview rooms in their own colour, and add an About box","body":"Brush, rectangle and circle previews take the room outline colour, so no tool changes hue on release.\nThe polygon's line to the cursor takes the mode colour, faded; the close halo takes the selected-room gold.\nNew About box behind an i button beside the shortcut legend: mark, version, repo. DM view only.\nThe version reads app.getVersion() over a new app-version IPC, and hides itself outside Electron.\nSplash tagline is now PREPARE LESS, PLAY BETTER.\nCLAUDE.md registers about.js; the 1.7.7 scene-switch notes ride along into docs/."},
  {"version":"1.7.7","date":"2026-08-09","note":"Switch scenes behind the fog itself","body":"The player's scene switch is fog closing over the old map, a pause, then fog clearing off the new one.\nFog colour crosses to the incoming scene's while the fog is closing, so mismatched scenes no longer pop.\nThe cloud texture holds its scale and position across a switch instead of zooming.\nThe scene name is gone from the transition and is no longer sent to the player.\nHalf-shrouded is wired up in the toolbar, and disables while the brush is picked.\nRoom outline colours come from one shared table, so a room keeps its colour when it closes.\nLegend, scene manager and UI-scale controls restyled off the old glass-panel look.\nNew transition capture tools under tools/, outside the build."},
  {"version":"1.7.6","date":"2026-08-08","note":"Carry the module text in the backup zip","body":"Export writes moduleText.json at the zip root, one entry per campaign, not per scene.\nRestore adopts it after the scenes are saved: silently when nothing is loaded, behind a confirm naming both books when one is.\nA storage failure reports itself and leaves the restored scenes alone; a zip without the entry restores exactly as before.\nmoduleText.js owns the format either way - backup.js asks for a payload and hands one back.\nDocs: the wrap entries for the error dialog and the deleted export modal ride along."},
  {"version":"1.7.5","date":"2026-08-08","note":"Show errors in the app, and reword every tooltip and message","body":"Route every error through the app's own dialog; no alert() ships.\nFix the room name field refusing a caret after an error is dismissed.\nAdd messageDialog(), confirmDialog's one-button variant for statements.\nReword every tooltip, placeholder and message; no em-dashes in the interface.\nRecover from a failed scene load without waiting for the message to close.\nRemove the unreachable backup export modal, its markup and its styles.\nRemove the unused doRestore path and the show-open-dialog IPC."},
  {"version":"1.7.4","date":"2026-08-07","note":"Use far less memory on animated maps","body":"Player map texture is now sized to the Player's screen rather than to the map\nDM no longer allocates the two fog transition canvases only the Player reads\nFog blur reuses its padded canvas instead of allocating one per reveal\nUndo and redo share one byte budget; redo previously had no cap at all\nPlayer texture coverage drops from 3x to 2x on oversized image maps\nNew memProbe.js, a memory-footprint probe, inert unless ?memprobe=1\nDrop the dead texture-pool flush from the minimize handler","tag":"v1.7.4"},
  {"version":"1.7.3","date":"2026-08-06","note":"Draw rooms without the card in the way, and keep walls straight","body":"Prep-time drawing feel, all DM side. Nothing reaches the Player and no saved data changes.\n\nDrawing a room no longer opens the room card\n- Rectangle, circle and polygon each create the room with nothing selected, so the\n  card can't cover the map while you draw the next one. Naming is a second pass with\n  Select. This matches what floor-plan import already did.\n- Visibility is still keyed to selection alone, so the card survives tool switches.\n\nNew \"straighten walls\" toggle in the toolbar\n- When a corner is already nearly level with the one before it, it snaps square. A\n  wall you genuinely want diagonal stays diagonal - it's an alignment nudge, not a\n  lock on where the mouse can go.\n- Works while dragging a corner of a finished room too, snapping to either neighbour.\n- The slack is in screen pixels, so it feels the same at every zoom. Grid snap runs\n  first and this layers on top. Off at startup, not saved anywhere.\n- New pure helper snapToAxis in fogGeometry.js, with tests.\n\nThe room card now places itself clear of the whole room\n- It was anchored on the room's centre point, so any room bigger than the card\n  swallowed it. clampPanelPosition now takes the room's bounding box and picks the\n  first side that clears it: above, below, right, left.\n- It holds still for the length of a vertex or edge drag instead of flipping sides\n  as the room reshapes under the pointer, and re-places once on release.\n- Fixed alongside: the card never re-placed on release at all, only when you next\n  moved the mouse. All four drag-release paths in tools.js now repaint.\n\nToolbar: a dark pill means pick one of these\n- Snap to grid and straighten walls left the fog-mode pill and became bare toggles\n  behind a hairline, outlined blue when on. A lone toggle in a pill read as harmless;\n  two made the pill say something false.\n- The tool row keeps its outlined style despite also being pick-one. That's\n  deliberate and recorded in the dm-ui skill so it doesn't get \"fixed\" later.\n\nOpacity slider had a one-pixel colour fringe at both ends\n- background-origin defaulted to padding-box while the clip was border-box, so the\n  gradient was a pixel narrower than the track and wrapped into the border ring. One\n  line on .ev-slider. The fog and hue tracks had it too, hidden by their colours.\n\nDocs and tooling\n- DECISIONS.md: six entries, including an amendment to the old \"no automatic card\n  placement rule wins\" call, which this partly reverses.\n- ARCHITECTURE.md: the room card section described the old centre-point placement.\n- src/css/toolbar.css now maps to the dm-ui skill in guard-skill-hint.js, since the\n  pill-versus-toggle rule lives in stylesheet classes.\n- 436 tests passing, 12 new."},
  {"version":"1.7.1","date":"2026-08-06","note":"Stop cave maps producing rooms that are solid rock","body":"A mixed caves-and-rooms map came back with one giant polygon covering most of\nthe map plus three \"rooms\" that were freestanding rock formations, and two real\nrooms silently missing. Gibblet Crossing now gives 13 rooms, all real, none\nfalse.\n\nTelling a room from solid rock\n- A run of walls that closes on itself carrying no portal anywhere does not\n  bound a room. It is rock, or the cave's own shell. Every real room reaches\n  somewhere through a doorway, so its walls arrive as an open chain that closes\n  only once the portals are unioned in.\n- Measured rather than guessed: on the cave export the false rooms scored 100%,\n  100% and 84% of their outline in doorless wall and every real room scored\n  exactly zero. So the test is \"any at all\" and there is no size threshold to\n  tune, which was the trap the winding-not-area lesson already warned about.\n- It judges a whole connected run of walls, not one room, so a windowless cellar\n  or a prison cell keeps its building's doors and survives. Only a structure\n  isolated from everything else is refused. A floor that is one sealed room -\n  an attic reached by a hatch - comes back empty rather than wrong.\n- vttDoorlessWalls + vttRingOnDoorlessWall in vttPlan.js, with a keepDoorless\n  opt-out and a refusedSolid count on the result. Computed on the wall-only\n  graph, T-split first, or a door in one wall leaves the other three looking\n  like an untouched ring and the whole building is refused.\n\nRooms that open onto a cave were being lost\n- Both ends of such a room's open side bridged sideways into the rock a few feet\n  away, nearer than each other. That glues the wall to the cave, closes nothing,\n  and spends the ends so the real partner is never found. 8 of the 10 bridges on\n  the cave map were that mistake, and widening the reach could not fix it.\n- Doorless walls are now excluded as bridge targets, so the two sides of an\n  opening can find each other.\n- Their ends sit 3.7 and 4.3 squares apart, past the 2.5 a lone stub is allowed,\n  so a mutual pair - both ends picking each other - now reaches\n  VTT_CLOSE_PAIR_MAX 5. That is much better evidence than a stub projecting onto\n  some wall's mid-span, which keeps the tight ceiling. Tightening the base\n  ceiling tightens both, so closeGapMax 0 still means no closing at all.\n- VTT_OPEN_WALL_MAX_GAP 4 to 6, to stay above the widest thing closing reaches.\n\nTests\n- Second real fixture: test/fixtures/cave-map.dd2vtt, the Gibblet Crossing\n  export with its 9MB embedded JPEG blanked, 30KB on disk.\n- 12 new cases covering the cave map, the sealed-vault and attic behaviour, the\n  rock-steals-a-stub bug, and the two ceilings. 424 green.\n- Two existing synthetic sheds had no door on them, which the new rule correctly\n  reads as rock, so they were given the door a real export always has.\n\nAlso\n- tools/inspect-plan.js: dumps a .dd2vtt's arrays, graph and every face with\n  area and winding before classification. Outside the build glob. This is how\n  the diagnosis was done.\n- Docs: the floor-plan section of ARCHITECTURE.md covers cave handling, two new\n  entries in DECISIONS.md, and the binding rules added to the floor-plan skill.\n\nKnown and accepted: the cave's own chambers are one continuous space with no\nwall between them, so nothing in the file says where one ends. Cutting the\ncavern polygon by hand is the intended route. A bridged opening is a straight\ncut across the mouth."},
  {"version":"1.7.0","date":"2026-08-06","note":"Draw a map's rooms from the floor plan it came with","body":"Dungeon Alchemist writes a .dd2vtt floor plan beside every map it exports. Drop\nthe map and Evermist finds it, then offers to draw all the rooms at once. A\n2-3 minute job instead of tracing polygons by hand.\n\nAuto-polygons\n\n- Dropping a map finds its sibling floor plan and shows a notice with the room\n  count. It has no backdrop, so the map stays pannable while it is up - a found\n  plan is good news, not a question that must be answered first.\n- Draw Rooms sits in the Fog tab's own Rooms group, enabled only on a scene\n  whose map actually came with a plan. It draws every room in one press.\n- A .dd2vtt dropped on its own attaches to the open scene, for a plan that got\n  separated from its map.\n- The plan is stored on the scene, so the button survives a restart and an\n  export/import round trip.\n- Rooms arrive as Room 1..Room N. The name field's module-text dropdown fills\n  them from there.\n\nThe geometry (src/vttPlan.js, pure and dependency-free, 37 tests)\n\n- Wall segments are unioned with the portals that fill their gaps, edges split\n  at T-junctions, then the planar faces are walked and classified by winding\n  direction. Interior faces are rooms, opposite winding is the island boundary.\n- Bounded gap closing: a loose wall end bridges to whatever it almost reaches\n  within 2.5 squares, gated on the two ends being each other's nearest feature\n  and on a minimum face area so a corner bridge cannot chip off a sliver. A\n  room missing an entire wall stays refused, which is correct - there are no\n  two ends to join.\n- Coordinates convert as (coord - map_origin) * pixels_per_grid. Dropping the\n  origin term leaves every room correctly shaped and uniformly displaced,\n  invisible on a zero-origin export and wrong on any other.\n- The test fixture is a real export with a square room, a quarter-circle room,\n  a round room and a deliberately broken one.\n\nPlumbing\n\n- New find-floor-plan IPC is deliberately narrow: main derives the sibling path\n  from the map's own path and will not read an arbitrary one. A floor plan is\n  untrusted input. Returns null on any failure, so an unreadable plan behaves\n  exactly like no plan and cannot strand the import overlay.\n- backup.js field lists carry floorPlan on both export and restore. Those lists\n  are whitelists, so a field missing from them is dropped silently.\n\nConfirm dialog polish\n\n- 320px to match the app's other floating panels, so a two-line question stops\n  wrapping mid-clause. A real size step between the question and the body text,\n  and a right-aligned footer with a quieter Cancel so the eye lands on the\n  action rather than splitting evenly between two answers.\n\nDocs and tooling\n\n- CLAUDE.md is down from 402 lines to 219 by relocation, with nothing deleted:\n  stylesheet rules moved to src/css/CLAUDE.md, and three rule clusters into\n  .claude/skills/ as floor-plan, module-text and dm-ui. A script asserted every\n  old line lands in exactly one destination.\n- Rules that cannot be triggered by filename deliberately stayed put. \"Rooms\n  are polygons\" governs 16 modules, so a skill keyed on room editing would miss\n  the session editing sceneManager.js, and the penalty there is silent data\n  loss in every saved scene.\n- New guard-skill-hint.js PreToolUse hook names the skill that owns a file\n  before it gets edited, because a pointer inside a doc is not a trigger."},
  {"version":"1.6.5","date":"2026-08-04","note":"Fix half-shroud doing nothing on ground the party already cleared","body":"Half-shroud never worked on the room it was built for. It erased a percentage of the\nfog over the room, and erasing needs fog to be there. Once the ground was already\nclear - a brush stroke, a Reveal All, or the room's own earlier Reveal - there was\nnothing left to erase, so marking the room Half changed nothing on screen and the\ndensity slider looked dead at every value.\n\nWhich is exactly the room Half is for. \"Explored, but the party isn't there now\"\nmeans the party has already been in it.\n\nHalf now clears the room fully like a Reveal, then paints fog back at the density\nyou set. The state is absolute, so the room lands on that density whatever was\nunderneath it. The feathered edge still ramps from the surrounding fog down into\nthe room, so it doesn't read as a hard-edged patch.\n\nNothing new is written to disk, so saved scenes and backup zips load unchanged. One\nvisible difference on old maps: a Half room overlapping brush-revealed ground now\ndims that overlap, where before it left it alone.\n\nDocs updated where they described the old subtractive behaviour.","tag":"v1.6.5"},
  {"version":"1.6.4","date":"2026-08-03","note":"Split the docs three ways, and cut the comments back","body":"Housekeeping release. Nothing in the app behaves differently - this is\ndocumentation, one new guard hook, and comment-only edits in src/.\n\nDocs split into three files with one job each:\n- CLAUDE.md is rules only, cut from 38.5KB to 23.7KB. One section had\n  grown to 80.7% of the file; the largest is now 28%.\n- docs/ARCHITECTURE.md rewritten. It was missing seven modules and it\n  told readers the deep version lived in CLAUDE.md, which is most of\n  why the \"no history here\" rule failed for months.\n- docs/DECISIONS.md is new: the ledger of what was tried, rejected,\n  reverted or parked, so that reasoning stops being smuggled into\n  CLAUDE.md as narrative.\n\nNew guard hook keeps it that way:\n- .claude/hooks/guard-claudemd.js blocks any edit that grows CLAUDE.md,\n  same ratcheting shape as the existing index.html blob guard. Measured\n  in bytes, not lines, because the old file was 162 lines of very long\n  paragraphs. Its block message names which of the other two docs the\n  new text belongs in.\n\nComment trim across the six heaviest files:\n- src/ goes from 22.6% comments to 19.3%. state.js, moduleText.js,\n  pdfExtract.js, confirmDialog.js, pdfLayout.js and roomPanel.js lose\n  350 comment lines between them.\n- Rules, one clause of reasoning, and trap warnings all stay. What went\n  is measurement dates, \"an earlier version tried X\", and anything that\n  restated the code or duplicated CLAUDE.md.\n- Verified by stripping comments from both versions and diffing the\n  pure code, per file. That caught a real regression the tests could\n  not see: retyping a line in mtSplitLines turned a literal\n  non-breaking space inside a character class into an ordinary space,\n  which would have stopped NBSPs being normalised. Fixed, and the\n  comment warning about the invisible characters is back.\n\n375 tests green.","tag":"v1.6.4"},
  {"version":"1.6.3","date":"2026-08-02","note":"Fix the DM overlay trailing the map, and lift the cap while panning","body":"Dragging the DM view had the room outlines, labels and room card sliding\nbehind the map they sit on, and the whole pan felt heavy on a high-refresh\ndisplay. Two separate causes, one shared root: something was off the clock.\n\nOverlay trailing the map\n- 1.6.1 put the map, fog and grid on one shared 30fps clock and measured them\n  landing 0.5ms apart. The Canvas-2D overlay never joined them. It repainted\n  once per mouse event, so on a 180Hz display it ran roughly six times faster\n  than everything underneath, and the layers slid against each other during a\n  drag. Same two-clock bug 1.6.1 fixed for the other layers.\n- The overlay is also the heaviest thing on screen during a drag - it walks\n  every polygon, lays out every label and repositions the room card - so\n  running it at mouse rate starved the rAF callbacks the capped layers ride,\n  and those arrived late and unevenly on top of being capped.\n- The pan handler painted it twice per event, the first time with the pan\n  values from before the move. That stale paint is what read as the polygons\n  drifting slower than the map.\n- New scheduleCursor() in render.js: the viewport gestures request an overlay\n  repaint on the shared clock instead of painting inline. drawCursor() clears\n  the flag itself, so a discrete caller can never be undone by a stale\n  scheduled repaint landing a tick later - mouseleave needs that.\n- Hover keeps its inline paint, so the brush ring still tracks the pointer at\n  full rate. tools.js and roomPanel.js still call drawCursor() directly and\n  should: they fire on discrete edits, not per mouse event.\n- DM-only, which is why the Player was never affected. The Player has no\n  rooms, no outlines and no cursor, so nothing over there runs off-clock.\n\nHeavy-feeling pan\n- The 30fps cap is sized for idle, which is where it earns its keep: fog\n  animation loops the whole session whether the DM touches anything or not.\n  A pan is a two-second burst, and at 30fps it sits a frame and a half behind\n  the hand.\n- boostRender() lifts the cap for the length of a DM viewport gesture and the\n  loop drops back when it stops. Measured 1.5% CPU idle, 7-9% during an active\n  pan, back to 1.5% after.\n- Expressed as a deadline, not an on/off pair. A pair has to catch every way a\n  gesture can end - mouseup, mouseleave, alt released mid-drag, window blur,\n  and a wheel zoom, which has no end event at all - and one missed path leaves\n  the renderer uncapped for the rest of the session, silently. With a deadline\n  the loop re-caps itself, so a missed event costs 250ms and not the session.\n  Verified it recovers from all of those plus a scene switch rebuilding the\n  renderer mid-boost.\n- Guarded to the DM. The Player runs a TV where the sync path and not the\n  frame rate is the limit.\n\nFog animation is on its own time-based rAF, so uncapping the ticker does not\nchange cloud drift speed. The 10Hz cloud blend throttle from 1.6.1 is\nuntouched.\n\n375 tests pass. Neither change is unit-testable - both are DOM-coupled and the\nverdict is what a drag looks like on a 180Hz monitor."},
  {"version":"1.6.2","date":"2026-08-02","note":"Module sub-locations, and the app asks its own questions now","body":"Module text import now finds SUB-LOCATIONS. A published module keys a building\nwith one number and its rooms with letters - N6 is the undertaker's shop, N6А\nthrough N6F are the six rooms inside it. The parser only matched \"number, dot,\nname\", so the whole shop arrived as one enormous N6 entry the DM had to split by\nhand. That is the most common shape in the town chapters.\n\n- The heading pattern accepts one trailing letter, and it becomes part of the\n  key shown in the dropdown, the import list and the map label. Written exactly\n  as the book has it.\n- Sub-locations sequence on UNIQUENESS of the letter under the parent number,\n  never on letter order. No ordinal survives the real data: one shop's six rooms\n  are keyed Cyrillic А В С Е beside Latin D F, and a chapter keyed purely\n  Cyrillic А Б В folds А and В onto the Latin scale while Б stays Cyrillic, so\n  В sorts below Б and that room disappears. Uniqueness needs no alphabet.\n- The parent bounds it instead: a sub may sit on the number the sequence has\n  reached, or open the next one when the parent heading was lost in extraction.\n  A sub numbered below the current room is a cross-reference in body text -\n  \"(см. область N6e)\" is in the sample - and is dropped.\n- Nine new tests cover the mixed-alphabet shop, the Cyrillic-only chapter, the\n  duplicate letter and the below-parent reference.\n- Widened the key column in the dropdown and the import list, since \"N6А.\" is\n  wider than the old floor and pushed that row's name out of line.\n\nFIXED: the room card's fields going dead after replacing a module name.\nReported repro: pick a name from the module list, pick a different one, answer\nthe \"replace description?\" question, then click the name field - no caret, no\ndropdown, though ctrl+A and drag-select still worked, and the description went\nthe same way.\n\n- The cause was the native confirm() itself. It is a separate OS window, and\n  closing one leaves the page's focus desynced from the field that had it: the\n  field stays the document's active element while the caret machinery lets go,\n  so a click places nothing and fires no focus event, which is also why the\n  dropdown never reopened. Nothing inside the page can repair that state.\n- New src/confirmDialog.js replaces it with an in-app dialog on the app's own\n  panel shell - flat card, hairline border, two equal buttons behind a footer\n  line, Escape and backdrop cancel, scales with the UI slider. It answers\n  asynchronously, so callers split into \"what happens regardless\" and \"what\n  happens on yes\".\n- applyModuleEntryToRoom writes the NAME up front and defers only the\n  description. Opening the dialog moves focus, which blurs the name field and\n  runs its commit - that commit has to find the new value already there or it\n  writes the old text back. It also makes \"Keep mine\" mean what it says: the\n  rename still lands.\n- pushUndo is now lazy, on the first write that actually happens, so declining\n  the question cannot leave a Ctrl+Z that reverses nothing.\n- Converted the import panel's \"Remove Module Text\" confirm as well. Those were\n  the only two native dialogs in the app, and CLAUDE.md now bans them outright.\n- The dropdown acts on click, with mousedown left doing nothing but\n  preventDefault. That keeps a dialog out of the middle of a mouse gesture so\n  the matching mouseup is always delivered - a smaller, separate version of the\n  same category of bug."},
  {"version":"1.6.1","date":"2026-08-02","note":"Fix the video map import hang, cap rendering at 30fps","body":"Fixes a blocker: importing a new animated map hung forever on \"Saving video\nmap...\". Electron 32 removed File.path, so since the Electron 43 bump in 1.4.4\nthe renderer was handing the main process an undefined path. The copy rejected,\nand with no error handling around it the progress overlay was never dismissed.\nExisting video scenes were unaffected, which is why it went unnoticed - they\nload from disk and never ask for a file path.\n\nVideo map import\n- New persistVideoMap() in sceneManager: streams the file to disk when a real\n  path is available, falls back to sending bytes when it isn't. Both main\n  process handlers already existed and were fine.\n- Exposed webUtils.getPathForFile through preload as the replacement for the\n  removed File.path. It has to live in the preload, not the renderer.\n- Both save paths now catch failures, always dismiss the progress overlay, and\n  fall back to the legacy in-database blob rather than hanging.\n- Same fix for .zip backup restore, which had been falling through to\n  \"Importing a .zip backup needs the desktop app\" while in the desktop app.\n\nPerformance\n- Render loop capped at 30fps via APP_MAX_FPS. On a 180Hz display this is a\n  measured 4.7x drop in renderer CPU and 6.8x overall.\n- The cap lives on ONE clock: render.js's dirty-flag loop now rides the PixiJS\n  ticker (pumpDirtyRender, registered above Pixi's own render) instead of its\n  own rAF. Two independently throttled loops hold the same interval but not the\n  same phase, which let the grid and fog layers lead the map by up to 33ms\n  during a pan. Sharing a clock drops that to 0.5ms, tighter than before the\n  change.\n- Cloud blend rebuild throttled to 10Hz (was every frame) and the DM's 512px\n  cloud texture upload gated on the blend actually changing. Morph speed\n  measured unchanged at 0.348 vs 0.350 frames/sec.\n- The existing video fog throttle still wins while a video plays, preserving\n  today's slower morph on animated maps.\n\nRemoved the deprecated FPS slider\n- It was a display:none row, unreachable since the panel redesign. Deleted the\n  markup, its wiring, the fpsToFrameInterval helper and its tests, and the\n  videoFrameIntervalMs field from the DM to Player sync message.\n- The 24fps video throttle itself stays - video.js reads it every frame. It is\n  now a fixed constant.\n\n365 tests pass.","tag":"v1.6.1"},
  {"version":"1.6.0","date":"2026-08-01","note":"Module text import: read the book, fill the rooms","body":"Load a published module once and every room's name field becomes a searchable\nlist of its locations. Pick one, and the room gets the module's name and its\ndescription together. Prep for an 80-room castle stops being an 80-round trip\ninto a badly formatted PDF.\n\nThe book comes in as a file\n- .pdf, .txt or .md. A module ships as a PDF, so the app reads the PDF rather\n  than asking you to export text first. Measured on a real 255-page module:\n  ~1.4s, 301 locations, ~900KB stored.\n- Reading order is columns first, then lines (src/pdfLayout.js). A two-column\n  page's left and right lines share a baseline, so grouping by y merges them and\n  interleaves the columns sentence by sentence. Spanning lines cut the page into\n  bands so a mid-page heading keeps its rooms.\n- Text files decode UTF-8 first and Windows-1251 second, strictly. A CP1251 .txt\n  from an older PDF tool otherwise arrives as a page of mojibake with no\n  explanation. Anything that isn't prose gets named (\".docx\", \"an RTF file\")\n  instead of parsed as one.\n\nThe parser, tuned against the real book\n- Splits at numbered headings, with one capital prefix allowed as part of the\n  key (\"K12. Chapel\") - that's how a big dungeon numbers its rooms, and a\n  digit-only pattern finds nothing in the chapter you most want. Castle\n  Ravenloft parses 88 of 88.\n- Greedy numeric continuation per prefix, so a numbered list in body prose\n  can't hijack the sequence, and a cross-reference inside a room's own text\n  can't skip five rooms.\n- Page furniture goes by \"the same text seen with a different number attached\",\n  never by a repeat count - a count deletes real sub-headings that recur\n  because several rooms share a feature.\n- Paragraph recovery, because the extraction contains no blank lines at all.\n  Without it every room arrives as one wall of text in a 270px card you read\n  aloud from.\n- Everything above is a pure kernel with unit tests on synthetic fixtures\n  (test/moduleText.test.js, test/pdfLayout.test.js). 234 -> 363 tests.\n\nPDF parsing is isolated, not trusted\n- A campaign module is a file from somewhere else and pdf.js is a large parser\n  for a format built to carry embedded programs, so it runs in a utilityProcess\n  (src/pdfExtract.js) forked per import and killed as soon as it answers. No\n  Electron APIs, no channel to any renderer, no state across imports, and a\n  timeout backstop for a file that makes the parser never return.\n- Verified on the built .exe, since npm start can't see this class of bug:\n  fork-from-asar resolves the packed entry and its requires, extraction runs in\n  451ms including process spawn, and a corrupt PDF comes back as a clean\n  \"Invalid PDF structure.\" rather than a hang.\n\nCampaign-level, offline, and never in your way\n- Entries live in localStorage, not in a scene or a backup: one module serves\n  every map in it. Only parsed entries are stored, never the raw file.\n- No LLM, no network. The app still runs standalone from file://.\n- No auto-assign and no \"fill all rooms\". Real module text has sub-locations -\n  one heading serving several polygons - so any 1:1 mapping desyncs within a few\n  rooms. You picking is the one irreducible step, so it's the only step.\n- Picking is one undo. A description you wrote yourself is never replaced\n  without asking, and declining fills only the name.\n\nImport panel: three controls\n- Choose file, Remove, Close, in the app's own panel style (flat #1a1a1c,\n  hairline border, stock cp-* buttons) instead of the old purple glass modal.\n- Gone: the paste box (nobody pastes 300 pages into a 320px panel), the Preview\n  button (choosing a file already parses, so the button only ever re-read an\n  empty textarea and told you to paste something first), and the paragraph\n  explaining the parser's rules (nothing you can act on - you're not going to\n  re-typeset a book).\n- The panel now lists what's actually loaded, every time it opens, with a char\n  count per room so an empty description is visible at a glance. That's the one\n  thing the old Preview never did.\n- Importing happens on choose. An empty parse never writes, so a wrong file\n  can't wipe a good import, and Remove is right there.\n\nReview pass, before this went out\n- Fixed: picking the same file twice did nothing. A file input fires no change\n  event for an identical file and nothing cleared it, so re-picking after a bad\n  parse was a silently dead button.\n- Room description cap raised from 2000 to 20000 characters. A single keyed\n  location routinely runs past 2000, and truncation here is silent. 20000 sits\n  between the legitimate worst case (a room that absorbed a sidebar, ~10K) and\n  the pathological one the cap exists for (a failed parse dumping a whole\n  chapter into one room).\n- Dropped three fields parseModuleText returned that nothing read, fixed a\n  storage-limit comment that overstated the headroom by 4x, and stopped hiding\n  the scrollbar on the one panel surface that scrolls.\n\nAlso\n- Packaging: pdfjs-dist is unpacked from the asar and loaded by explicit path\n  with GlobalWorkerOptions.workerSrc set, and @napi-rs is excluded (37MB of\n  optional native canvas that text extraction doesn't need).\n- CLAUDE.md's module-text rules rewritten as instructions rather than narrative,\n  per its own no-history convention.","tag":"v1.6.0"},
  {"version":"1.5.3","date":"2026-08-01","note":"Sync View: send the visible map region, not the DM's zoom","body":"Sync View sent the DM's zoom value, which is pixels-per-map-unit on the DM's\nown canvas. The Player replayed it against a differently sized canvas, so the\nTV covered a different amount of map than the DM was looking at - a 1920 TV\nshowed roughly 25% more in each direction than a 1536 laptop. Deterministic,\nnot drift, and it happened even when both screens were 16:9.\n\nWhat changed:\n\n- A view now crosses the wire as a REGION (centre plus viewW/viewH in map\n  units). The Player fits that region to its own screen, so it always shows\n  at least everything the DM sees. Where the aspects match it is exact edge\n  to edge; where they differ it fits rather than crops, so the players can\n  never see less than the DM.\n- The region is clipped to the map's bounds before sending. Nothing is ever\n  drawn outside the map, so the empty background around a zoomed-out map\n  carries no information - sending it made the Player reproduce the DM's\n  letterboxing and then add its own, leaving the map small and boxed in on\n  all four sides. With the clip the map fills the TV instead. On a 2000x1050\n  DM canvas against a 1281x806 TV that is 20% more map on screen. No effect\n  at all when the map covers the whole DM screen, which is most of play.\n- Fixed the minimap's dotted TV frame. minimapView.zoom is always in Player\n  terms, and Sync View was the one path writing a DM-terms zoom into it, so\n  pressing Sync left the frame wrong until the next drag or free-look report.\n\nNot changed, on purpose: Auto-sync still omits the view so the Player keeps\nits own pan and zoom, and the Player's own reports back to the DM are already\nin Player terms and pass through untouched.\n\nAlso tried and reverted: trimming the strip of canvas hidden behind the\ncontrol panel. Correct on paper, but it cropped the TV to the DM's readable\narea, which shifted the framing and took content away from the players that\nused to reach them. There is a note in dmVisibleRegion() not to re-add it.\n\nTests 215 to 234, all green. New pure helpers zoomToFitRegion and\nvisibleMapRegion in viewport.js are covered, including the never-crop\nproperty and the end-to-end case that matching aspects give an identical\nregion at any pixel size."},
  {"version":"1.5.2","date":"2026-08-01","note":"Split the CSS out of index.html into src/css/","body":"index.html carried a 1366-line <style> block, more than ten times the size of\nthe inline script that sits beside it. It is now eight stylesheets under\nsrc/css/, linked in cascade order. The page drops from 2119 lines to 759.\n\nThe split is by screen region, and each file is named to pair with the JS\nmodule that owns the same concern:\n\n  base.css          reset, floating panels, canvas layers, player mode\n  controlPanel.css  the Fog / Grid / Player panel\n  toolbar.css       bottom toolbar and its sub-panels\n  roomCard.css      the room card\n  playerPane.css    the Player tab\n  legend.css        shortcut legend\n  sceneManager.css  scene dropdown and undo toast\n  overlays.css      backup modal, scene fade, map progress, landing\n\nThis is a pure move - no selector renamed, no rule merged, nothing reformatted.\nReassembling the eight files in their original order and diffing against the\nold block gives zero difference, byte for byte.\n\nTwo sections load earlier than they used to (canvas layers and player mode both\nsit in base.css now). That is the only reorder, and it is safe: of the 197 rules\nthey jumped over, exactly two can target the same elements, and both lose to the\nhoisted rule's !important. Verified against the pre-split page as well - 493\nelements across 36 computed properties, every panel and modal open, player mode\non, zero differences.\n\nAlso in this change:\n\n- package.json build.files gains \"src/css/**/*.css\". It is a strict whitelist\n  and the existing src/**/*.js glob does not match .css, so without this the\n  packaged .exe would ship with no styling at all. Confirmed the built asar\n  carries all eight files.\n- The index.html guard hook (.claude/hooks/guard-blob.js) gains a second rule:\n  a <style> before <body> is now blocked outright, pointing at src/css/. The\n  check is scoped to the head on purpose, since the body is full of inline SVG\n  and an <svg> may legally carry its own <style>. The existing blob measurement\n  and the fail-open design are unchanged.\n- CLAUDE.md and docs/ARCHITECTURE.md updated for the new layout, the widened\n  build glob, and the guard's second rule."},
  {"version":"1.5.1","date":"2026-07-31","note":"Half-shroud: a third fog state, with a density slider","body":"Rooms now have a third fog state between Revealed and Shrouded: a room the\nparty has explored but isn't standing in. Partly fogged, still readable\nunderneath. This is a trial run - the point is to use it at the table and\ndecide whether it earns its place.\n\nHow to use it\n- The room card's fog pill: the Half segment is live now instead of greyed out.\n- T on a selected room cycles reveal > shroud > half > reveal.\n- A new \"Half\" slider in Advanced Settings sets how much fog remains. 0 is\n  fully revealed, 100 is fully shrouded, default 50. One global value, saved\n  between restarts, never written into a scene or a backup.\n- Half rooms get their own teal outline on the DM map so you can read the\n  three states apart at a glance.\n\nJudge the density on the Player window, not the DM window. The DM view draws\nfog at 55% so a 50 setting looks like ~27% on your screen and 50% on the TV.\n\nExport a backup before you first use Half on a real scene. Half is saved into\nscenes and backups as a plain mode string, so if this gets pulled back out,\nsaved half rooms would come back as full reveals.\n\nHow it works\n- applyPolygonToFog rides the existing reveal path for half, just at reduced\n  erase strength, so the feathered edge and the cloud texture come along for\n  free. No second texture and no reduced blur.\n- The interior is flattened on the scratch mask rather than on the fog canvas.\n  A reveal wipes cloud-erosion residue afterwards with a hard clearRect, but a\n  partial erase multiplies, so residue left in the mask would have shown up as\n  blotchy density. The reveal path itself is unchanged.\n- The erase is subtractive, so a Half room overlapping ground you already\n  brush-revealed shows no change in the overlap. That's deliberate: you can't\n  half-forget the room the party is standing in.\n- The Player window and the minimap needed no changes. Fog crosses as pixels,\n  so the partial alpha propagates to both on its own.\n\nVerified: interior lands dead flat at every slider position, the half edge is\nas soft as a revealed edge, cloud texture is intact at half opacity on the\nreal Player composite, and half survives scene switches, undo/redo, restart\nand a backup round trip. 215 tests green. The inline script is untouched.\n\nNot built: the bottom toolbar's Half brush is still inert. It needs its own\ntool state and paint path, and it tests nothing the room card's pill doesn't."},
  {"version":"1.5.0","date":"2026-07-31","note":"Room notes: name and describe rooms, with labels on the map","body":"Rooms now carry content. Select a room and a floating card lets you name it and\nwrite freeform notes - what the party sees, what's hidden - written during prep\nand scanned at the table. Room names are drawn on the DM map itself, so the\ndungeon reads at a glance instead of needing a hover to identify anything.\nPress L to toggle the labels. None of this reaches the Player: fog crosses as\npixels, so room notes are DM-only with no channel to strip.\n\nRooms (new)\n- src/roomPanel.js: the room card, the map labels, and a unit-tested pure kernel\n  for the label geometry. Replaces the old purple #panel-poly-ctx panel.\n- The card is movable (drag its bar) and its description is resizable, because a\n  card floating over the map will sometimes cover the handles you selected the\n  room by, and no placement rule wins that in general. The description height is\n  remembered as one global preference, never per-room and never in a scene.\n- Labels sit top-left inside the room via a scanline fit, so a circle and a\n  heavily rounded rectangle both work without a per-shape special case. Type\n  size tracks zoom gently and is clamped at both ends. Names too small to read\n  hide themselves rather than drawing \"C...\".\n- The Rooms tab and src/roomList.js are deleted. A vertical room list was built\n  and rejected: the map is the better interface, since it's the biggest target\n  on screen and it shows an actual room instead of a room's name.\n\nFixes found along the way\n- Panel positioning was wrong under UI scaling. The screen-to-layout pixel\n  mapping is affine, a slope AND a constant, and only the slope was applied -\n  leaving a fixed ~8px offset that automatic placement hid but dragging exposes.\n  Both terms are now derived at runtime, so it self-calibrates on any engine.\n- Ctrl+Z no longer slams the card shut mid-read. Undo cleared the selection\n  unconditionally; it now keeps it when the room survived the undo.\n- Typing in the description no longer fires map shortcuts. The keydown guard\n  checked INPUT but not TEXTAREA, so a bare 'r' or Delete reached the map and\n  could switch tools or delete the room.\n- Reveal All / Shroud All refresh the card, which was otherwise showing stale\n  fog state until the next repaint.\n- Scene switch and scene delete now close the card and clear the label cache,\n  instead of leaving it floating over a new scene with the old room in it.\n\nInternal\n- polygons gains name and desc. Scenes saved before this load fine: the backfill\n  is an additive spread, never a field whitelist, which would silently drop\n  cornerRadii from every saved scene.\n- 74 new tests (215 total). CLAUDE.md documents the card's layout rules, the\n  affine zoom conversion, and the destructive-button pattern.\n- Inline script in index.html unchanged at 103 lines - this whole feature added\n  nothing to the blob.","tag":"v1.5.0"},
  {"version":"1.4.5","date":"2026-07-28","note":"Rebuild the Player tab UI + fix minimap zoom and fog veil","body":"Redesigns the Player tab in the control panel to match the Fog/Grid design\nsystem, and fixes three bugs found along the way. All existing controls do\nthe same thing - every visible control proxies its click to the original\nbutton, now hidden in #cp-legacy, so the toolbar.js / minimap.js /\nviewport.js wiring is untouched.\n\nPlayer tab\n- Four uniform label-plus-content sections: Window (open/close + fullscreen,\n  with the display resolution on the header row), Preview (minimap + lock),\n  View (zoom + sync view), Updates (auto/manual + send).\n- New Player zoom stepper: - / + step by one wheel notch, the % field takes a\n  typed value, arrow keys step it. Clamped to the existing 2-2000% limits and\n  kept in sync when zoom changes from the wheel, a drag, Sync View or a\n  Player free-look report.\n- Lock moved onto the preview as a floating icon button.\n- Open/Close Window button leads the pane. Blue outline and fill is the only\n  live indicator - no status dot, and the label swaps so the toggle is\n  discoverable.\n- Minimap preview is now square and shows more map than the TV does, with the\n  TV's own frame marked by two dotted lines. No fill and no dimming, so the\n  frame never obstructs the map underneath. This reverses the earlier\n  mirror-only decision, deliberately.\n\nButton vs toggle identity\n- A black inset pill (.cp-tabs / .cp-seg) now strictly means \"pick one of\n  these\". Independent actions (fullscreen, sync view, send) are .cp-btn\n  outlines instead, and value fields (.cp-stepper) use the light surface.\n- Adds .cp-btn-outline.active (blue outline + fill) and .cp-btn-icon.\n  Documented in CLAUDE.md so it does not drift back.\n\nBug fixes\n- Fog tint in the minimap composited with source-over and a full-canvas\n  fillRect, so it ignored the fog mask and washed fogTintColor over the whole\n  preview - a pure-white map with zero fog rendered as (209,199,245). Now\n  source-atop, as the comment above it always said it should be. Clears up\n  the minimap at every fog level, not just on revealed map.\n- Minimap wheel zoom pivoted about the cursor, which cannot change zoom\n  without shifting the view centre, so zooming off-centre also panned what\n  the players were looking at. Now pivots about the view centre and routes\n  through minimapSetZoom, so the wheel and the stepper agree exactly.\n- Minimap drag divided a CSS-pixel cursor delta by the canvas's 176px backing\n  store width, over-shooting every drag by their ratio (~1.42x at the default\n  UI scale). Now measured against the canvas's true on-screen size via\n  offsetWidth x --ui-zoom.\n- Open Player Window did nothing on a second press, because window.open() on\n  an already-open named window just re-navigates it. It now closes the Player.\n\nCleanup\n- Drops the old #minimap-player-controls styling, the orphaned .panel-sep\n  rule, and the follow / free-look indicator.\n- CLAUDE.md module map records the minimap zoom API, the Player tab proxy\n  layer, and the button/toggle identity rule."},
  {"version":"1.4.4","date":"2026-07-28","note":"Bump engine to Electron 43 (Chromium 150) + electron-builder 26","body":"Move the desktop engine off Electron 28 (Chromium 120, late 2023) onto\nElectron 43 (Chromium 150), and its packaging tool from electron-builder 24\nto 26. Groundwork for retiring the CSS-zoom control-panel workarounds later,\nonce a real build confirms the newer Chromium fixes those bugs natively. No\nuser-facing change this release - the existing workarounds stay in place.\n\nDependencies:\n- electron ^28.0.0 -> ^43.0.0 (package.json)\n- electron-builder ^24.0.0 -> ^26.15.0 (package.json)\n- package-lock.json regenerated to match - must ship in the same commit or\n  the CI \"npm ci\" step fails on a mismatched lock\n\nCI:\n- release.yml: build runner Node 20 -> 22, the floor electron-builder 26's\n  @electron/* tooling is moving to (and off near-EOL Node 20). Unrelated to\n  the Node that Electron 43 bundles into the app runtime.\n\nVerified: npm install clean (no peer-dep conflicts), 141/141 tests green,\napp boots on Electron 43. Video-map stall fix (BackgroundVideoTrackOptimization\nswitch, main.js) and PixiJS fog still need confirming on a built .exe."},
  {"version":"1.4.3","date":"2026-07-28","note":"Tabbed Fog/Grid/Player control panel + UI bug fixes","body":"Replaces the old collapsible sidebar sections with a tabbed Fog / Grid / Player\ncontrol panel (new src/controlPanel.js). It's a presentational layer that drives\nthe existing hidden fog/grid controls, so all fog/grid/scene/player-sync logic is\nuntouched.\n\nControl panel\n- New tabbed layout: Fog, Grid, Player. Content width and padding aligned to the tab bar.\n- Two HSV colour pickers (SV canvas + hue + opacity + hex) feeding the existing colour inputs.\n- Animation and Grid Type rendered as toolbar-style segments (shared .cp-seg): black box, sleek toolbar-weight icons, blue-on-select, no outline.\n- Fog tab: Reveal All / Shroud All grouped up top under a \"Control\" header.\n- Advanced fog sliders float in a panel anchored beside the sidebar.\n\nBug fixes (all rooted in Electron 28 / Chromium 120's stale CSS `zoom` handling)\n- Colour picker no longer snaps to black: pick() reconstructs the canvas box from the pointer's own client/offset coords instead of getBoundingClientRect, which disagrees with ancestor `zoom` on old Chromium.\n- Advanced panel positioned from zoom-independent metrics (innerWidth + known widths) instead of getBoundingClientRect, so it sits beside the controls rather than mid-screen.\n- Grid offset X/Y fields no longer overflow: explicit flex-basis:0 + width:0 so old Chromium shrinks the inputs.\n- Opacity track rebuilt as a linear-gradient checkerboard (not conic, which fringed colour at the edges on old Chromium) with a dynamic transparent -> selected-colour overlay; stays visible on pure black.\n\nWiring & docs\n- toolbar.js calls initControlPanel last; removed the old section expand/collapse handlers.\n- fog.js / grid.js call refreshFogControlUI / refreshGridControlUI on scene restore so the panel tracks the active scene.\n- CLAUDE.md: added controlPanel.js (and minimap.js) to the module map and load order."},
  {"version":"1.4.2","date":"2026-07-27","note":"Rebuild Scene Manager as a dropdown with bulk ops, drag-reorder, undo","body":"Replaces the centered Scene Manager modal with a top-left dropdown built to the new design system. All behaviors are wired to real functionality.\n\nScene dropdown\n- Trigger pill shows the active scene name + chevron, with a \"+\" button beside it. Opens on click, closes on outside-click.\n- Cards use the gradient-thumbnail layout: 16:9 map thumbnail with the name overlaid; active scene gets a blue ring.\n- Click a card to load that scene.\n\nNew interactions\n- Inline rename: click a scene's name to edit it (Enter/blur saves, Esc cancels). The separate rename button is gone.\n- Drag to reorder scenes; the new order persists to IndexedDB via sortOrder.\n- Bulk options: per-card checkboxes, a header select-all (with indeterminate state), an \"N selected\" count, and Export + Delete actions that appear only while selecting.\n- \"+\" merges New Scene and Import - an image/video creates a new scene, a .zip runs a backup restore (auto-detected by file type). Export moved under bulk selection.\n- Undo toast after delete (\"X removed\" + 4s countdown), for both single and bulk deletes.\n\nBehavior changes\n- Delete no longer shows a blocking confirm dialog. It is instant and undoable; the real IndexedDB removal is deferred ~4s (cancelled by Undo, or committed early on window unload so it is never left half-done).\n- The old Export checklist modal is bypassed - bulk export runs off the current list selection. Its code remains but is no longer reached.\n\nCode organization\n- Scene-manager UI wiring moved out of toolbar.js into sceneManager.js (initSceneManagerUI), which owns the scene concern; toolbar.js just calls it.\n- backup.js: doRestore split into restoreFromZipPath so the \"+\" can restore a .zip by path.\n- No changes to the inline script; all logic lives in src/ modules.\n\nNotes\n- Import via \"+\" requires the desktop app (Electron), matching how backups already worked.\n- Fonts stay system-ui for offline (file://) use.\n\nVersion\n- Patch bump 1.4.1 to 1.4.2."},
  {"version":"1.4.1","date":"2026-07-27","note":"Redesign the bottom toolbar to the new design system (UI only)","body":"Reskins the DM bottom toolbar to the new low-ink design system. UI only - every button keeps its existing wiring; no logic files were touched\n\nToolbar\n- New dark bar (#1a1a1c, hairline border, soft shadow) replacing the purple glass look, with the design's tool icon set and a blue-outline active state.\n- Tools (Select, Polygon, Rectangle, Circle, Brush) restyled to 34px buttons.\n- Fog modes are now a 3-icon inset segment (empty / half / full circle); Revealed maps to the existing Reveal, Shrouded to the existing Shroud.\n- Snap moved off the floating panel and into the bar as its own segment. It's now always visible instead of hiding while Brush is active.\n- Brush size panel restyled to a thin slider plus a \"px\" chip (still read-only).\n\nNew functionality flagged, not built\n- Half-shrouded is present as a dimmed dummy button that does nothing. Real half-shroud fog is a separate feature for later.\n\nNotes\n- Kept the app's real keyboard shortcuts in the tooltips (Rectangle E, Snap N, Reveal R, Shroud S); the design mockup's alternate keymap was not adopted since that would be a logic change.\n- No Google Fonts added - stays offline-safe on file:// with a system mono fallback for the px chip."},
  {"version":"1.4.0","date":"2026-07-10","note":"Add Player minimap remote for the TV view","body":"New:\n- Minimap panel in the DM window's right column - a live mirror of exactly what the Player TV is showing, drawn at the TV's real aspect and orientation.\n- Drag the minimap to pan the Player view, scroll to zoom. It steers the Player camera directly, so you drive the TV without walking over to it.\n- Lock button freezes the view. It blocks accidental nudges on the minimap and also stops anyone poking the Player window (or the TV itself) from drifting the camera. Sync View still moves the Player when you press it on purpose.\n- The Player controls (Open Window, Sync View, Auto, Fullscreen, Send) now sit together under the minimap. The old collapsible Player section is gone.\n\nUnder the hood:\n- The Player window now reports its screen size when it opens and whenever it resizes, so the minimap always matches the TV's shape. A Player that opens while Lock is on comes up locked.\n- Grid drawing now scales to whatever view it's asked to render, which fixes grid alignment inside the minimap.\n- New src/minimap.js module; version bumped to 1.4.0.","tag":"v1.4.0"},
  {"version":"1.3.14","date":"2026-07-10","note":"Add backup.js + sceneManager.js tests, extend Stryker","body":"- backup.js: wrap DOM listener block in `typeof document` guard so the\n  file is require()-safe in Node; export resolveSceneName + mapExtFromScene\n- test/backup.test.js: 13 tests covering resolveSceneName (gap-fill,\n  collision chain, Set mutation) and mapExtFromScene (video/image/fallback paths)\n- sceneManager.js: export escHtml\n- test/sceneManager.test.js: 5 tests covering escHtml (all four escapes,\n  coercion, pinned single-quote passthrough)\n- stryker.conf.json: add mutation ranges for the three new functions\n- 141 tests total (was 123); mutation scores: sceneManager 100%,\n  backup 94% (2 equivalent mutants, unfixable by design)"},
  {"version":"1.3.13","date":"2026-07-10","note":"Fog/undo pure-kernel extraction + 20 new tests","body":"- Fixed cloudBlendIndices negative-pos bug (corrupt scene data could skip a cloud blend tick; euclidean modulo fix + 2 regression tests)\n- Extracted sampleWrappedNoise and fogTurbulence into fogGeometry.js; fog.js delegates via thin wrapper - zero behavior change\n- Extracted parseSceneFogSettings into fogGeometry.js; covers all falsy-but-valid traps (tintAlpha: 0, enabled: false, NaN anim fields)\n- Extracted evictUndoStack into undo.js with guarded export; covers the length > 1 floor and exact-boundary cases\n\nTests: 103 → 123 (fogGeometry.test.js + new undo.test.js)\nStryker config updated with line ranges for all new/modified functions; undo.js hits 100%, fogGeometry.js 83.7%"},
  {"version":"1.3.12","date":"2026-07-10","note":"Add tools.js tests, display/video coverage, Stryker mutation config","body":"- tools.js: export guard for pointInPolygon, distPointToSegment, segmentsIntersect; 16 new tests covering inside/outside, all four distance regimes, crossing coordinates, parallel/collinear, and open-interval boundary behavior\n- display.test.js: overhauled from 3 toothless tests to 11 - scaleFactor fallback (missing/string/null), workAreaSize preference over size, missing-width fallback, null raw input; NaN passthrough documented as a known gap (// KNOWN GAP comment)\n- video.test.js: two boundary tests for the scale >= 1 early-return; known-benign survivor (scale === 1 returns source either way) noted in both the test and the backlog\n- Stryker mutation testing installed (@stryker-mutator/core) with config scoped to line ranges of the three pure-function groups; npm run test:mutation wired; display.js scores 100%, tools/video gaps filed to backlog"},
  {"version":"1.3.11","date":"2026-07-10","note":"Extract render orchestration into render.js","body":"Moves the last real concern out of the inline blob in index.html into proper modules:\n\n- New src/render.js: syncSize, scheduleRender, getViewportSize, calcViewport, doRender, and drawCursor — the full dirty-flag render dispatcher and cursor/polygon overlay\n- scheduleAutoSync moved into src/viewport.js, alongside sendToPlayer where it belongs\n- Inline blob is now pure wiring: DOM refs, PixiJS init, init calls, lifecycle listeners\n\nNo behavior change. 77 tests green.","tag":"v1.3.11"},
  {"version":"1.3.10","date":"2026-07-09","note":"Extract map loading into mapLoader.js","body":"Moves image-map loading and the shared progress-bar helpers out of the index.html inline script into a new src/mapLoader.js module.\n\nWhat moved:\n- loadMapFromFile - image path only; video loading stays in video.js\n- showMapProgress / updateMapProgress / hideMapProgress - called by backup.js (~15x) and sceneManager.js\n- onVideoSaveProgress IPC listener block\n\nWhat stayed in the blob:\n- Breadcrumb comments pointing to video.js, tools.js, undo.js\n- All render helpers, DOM handles, fog globals, and video loading - untouched\n\nOther changes:\n- index.html: added <script src=\"src/mapLoader.js\"> between tools.js and undo.js\n- CLAUDE.md: reconciled the full load-order block (was missing mapLoader.js, undo.js, input.js, stress.js); added mapLoader.js to the target module map\n- package.json: version bump to 1.3.10\n\n77/77 tests pass."},
  {"version":"1.3.9","date":"2026-07-09","note":"Migrate shared state declarations to state.js","body":"Moves the entire declaration block from the inline <script> into src/state.js - config consts (ZOOM_FACTOR, POLY_CLOSE_RADIUS), map/video state, camera/pan-zoom, polygon, auto-sync, scene management, player sync/lerp, dirty flags, and player tex canvas.\n\n- index.html loses 59 lines of top-level declarations; a breadcrumb comment marks the spot\n- state.js gains them as one contiguous region with section headers preserved\n- CLAUDE.md: updated the state.js module-map entry to describe what it now owns\n- Pure relocation - no renames, no behavior change, 77/77 tests pass"},
  {"version":"1.3.8","date":"2026-07-09","note":"Extract mouse/keyboard handling into input.js","body":"Pulled the DM mouse/wheel handlers, keyboard shortcuts, shape helpers\n(setShape, updateContextPanels), and the legend toggle out of the\nindex.html inline script into src/input.js. One initInput() call in\nthe blob wires it in - same place as initToolbar/initPlayer.\n\n- ~185 lines removed from the inline blob\n- setShape, updateContextPanels, toggleLegend stay global (top-level\n  declarations) so toolbar.js and other modules can call them\n- Drag-drop stays in toolbar.js - not part of this extraction\n- CLAUDE.md load-order block corrected (added missing undo.js and\n  stress.js, inserted input.js in its real slot)\n- CLAUDE.md module map updated: input.js moved from \"needs extraction\"\n  to extracted\n\nKnown bug filed in backlog: controls unresponsive until \"Send\" is\nclicked on first launch - likely a focus/timing issue, not caused by\nthis change. Low priority."},
  {"version":"1.3.7","date":"2026-07-09","note":"Fix animated-map stutter when the Player window is open","body":"Fix - animated maps no longer stutter or freeze with two windows open\n- Root cause: the DM and Player both play the same scene, so both read the\n  same video file off disk at once. When their demands overlapped, Chromium\n  starved both - GPU decode dropped to zero and the map froze while the fog\n  kept moving. It only happened with the Player open; the DM alone was fine.\n- The Player now plays from its own in-memory copy of the clip instead of the\n  shared file, so the two windows never fight over it. The DM still plays from\n  disk.\n- Adds a read-video-file IPC (main.js) and readVideoFile bridge (preload.js);\n  the DM sends the scene id (viewport.js); the Player builds a blob and guards\n  against a mid-switch race (player.js).\n\nDiagnostics and stress harness (kept for future video work, not temporary)\n- On-screen video diag overlay (backtick key, both windows) and always-on disk\n  logging to userData/logs, with a [STALL-FLUSH] marker.\n- Overnight stress rig: npm run stress / npm run stress:control (src/stress.js)\n  cycles scenes and polygon reveals and watches for stalls.\n- Supporting plumbing: sceneStore lists mapType without loading blobs; the\n  Player URL inherits stress params; index.html loads the rig.\n\nLogging leash\n- Diag logs now rotate on launch. The live session keeps the stable filename;\n  older sessions are dated and pruned to the last 3 per mode, so the always-on\n  logs can't grow without bound."},
  {"version":"1.3.6","date":"2026-07-09","note":"Tidy repo root: runtime modules to src/, docs to docs/","body":"- Moved the 16 browser-runtime modules into src/ and the two long-form docs (ARCHITECTURE, Fog_animation_approaches) into docs/, so the GitHub page shows the README and GIFs near the top instead of behind a wall of loose files.\n- Repointed everything that referenced them: index.html script tags, 5 test require paths, and the ARCHITECTURE/CLAUDE/README links.\n- build.files now uses a src/**/*.js glob, so future modules ship in the Electron package without editing package.json by hand. Updated CLAUDE.md's layout notes and load-order block to match.\n- main.js, preload.js, index.html and splash.html stay at root as the Electron entry points.\n- Pure relocation, no logic changes. All 77 tests green. Bumped version to 1.3.6."},
  {"version":"1.3.5","date":"2026-07-08","note":"Extract video loading into video.js; partial jitter fix","body":"De-blob: moved video DOM compositing + file loading into video.js\n\nExtracted from the inline blob into the existing video.js (which already\nowned playback lifecycle):\n- videoDOMActive, activateVideoDom, deactivateVideoDom, syncVideoDomTransform\n- cleanupVideo\n- loadVideoFromFile\n- isVideoFile\n\nThese reunite with the rest of the video code and fix two forward-references\nvideo.js was already making into the blob. Pure move - no logic changes.\n\nVideo jitter investigation (partial fix, bug still open)\n\nRoot cause identified via a new permanent diagnostic overlay (backtick key,\nworks in both DM and Player): Chromium drains the video buffer periodically\n(readyState 4->2, event:waiting), causing visible jitter when playback resumes.\n\nThree mitigations shipped:\n- Removed the watchdog seek-kick (currentTime = currentTime) on rs=2 while\n  not paused - it was interrupting the browser's own refill and causing its\n  own jitter\n- onVideoWaiting now explicitly pauses the video (freezing the presentation\n  clock) and polls until rs>=3 before resuming - prevents the catch-up\n  sync-seek jump on refill\n- backgroundThrottling: false added to both DM and Player BrowserWindows in\n  main.js - prevents Chromium from stalling timers and media in background\n  windows (Player is almost always unfocused in real use)\n\nIntermittent jitter remains after all three - repro steps unclear, may be\nworse after heavy scene-switching. Diagnostic overlay is the right tool to\ncatch the next occurrence. Bug logged in backlog as item ③."},
  {"version":"1.3.3","date":"2026-07-08","note":"De-blob: extract player runtime into player.js","body":"Moves the entire player-mode runtime out of the inline <script> blob in\nindex.html into a new module player.js, following the same initToolbar()\npattern used by toolbar.js.\n\nWhat moved: cloud-texture pre-generation, the PLAYER_READY handshake,\nthe resize listener, the full window 'message' handler (map load, fog\nupdate, anim-params, scene-transition, view-snap, fullscreen), and the\nplayer pan/zoom event listeners.\n\nZero logic change — body is verbatim. The blob loses ~284 lines and gains\ntwo: a breadcrumb comment and `if (isPlayer) initPlayer();`.\n\n- player.js added to package.json build.files (required for Electron packaging)\n- Script tag inserted between toolbar.js and the inline blob (correct load order)\n- CLAUDE.md and ARCHITECTURE.md updated to document the new module\n\nSmoke-test note: DM path is unaffected. Verify the player window in the\npackaged .exe — post-PLAYER_READY, map delivery, fog updates, pan/zoom,\nscene transitions, and fullscreen toggle."},
  {"version":"1.3.2","date":"2026-07-08","note":"De-blob: extract four modules from inline script","body":"Continues dissolving the index.html inline blob. Four pure moves - no logic changes, no renames:\n\n- sceneManager.js (new) - entire scene engine: switchScene, createNewScene, initScenes, renderSceneManager, openSceneManager, closeSceneManager, startRenameScene, confirmDeleteScene, moveScene, generateThumbnail. switchGeneration moves with it (private to switchScene).\n- undo.js (new) - Undo/Redo: pushUndo, popUndo, redo, undoStack/redoStack/UNDO_MAX_BYTES.\n- tools.js - polygon lifecycle added: closeActivePolygon, deleteSelectedPolygon, toggleSelectedPolygon.\n- viewport.js - screenToMap and fitToScreen moved in.\n\nAll four files added to package.json build.files. Load order updated in index.html. CLAUDE.md module map and ARCHITECTURE.md files table updated to match. 77/77 tests green."},
  {"version":"1.3.1","date":"2026-07-07","note":"Extract DM toolbar wiring into toolbar.js","body":"Lifts the DM-only UI control wiring block (formerly index.html lines\n2521–2984) into a new toolbar.js module, wrapped verbatim in\ninitToolbar(). The inline blob calls it at the exact same source\nposition via `if (!isPlayer) initToolbar();` — execution order is\npreserved byte-for-byte.\n\nWhat moved: toolbar/tool buttons, brush/grid/fog sliders, fog color\npicker, animation presets and advanced sliders, poly context panel,\nscene-manager and backup modals, player-window controls, section\ncollapse toggles, UI-scale slider, and the DM-side player message\nlistener.\n\nWhat didn't move: the Player message receiver block, keyboard\nshortcuts, and mouse events — those are the future input.js concern.\n\nChanges:\n- toolbar.js: new file ('use strict' + initToolbar() wrapping the\n  verbatim body — no renames, no behavior changes)\n- index.html: script tag added after grid.js; block replaced with\n  one-liner\n- package.json: toolbar.js added to build.files (Electron packaging)\n- CLAUDE.md: load order and module map updated\n- ARCHITECTURE.md: toolbar.js row added to file table\n- Bumped version to 1.3.1"},
];
